import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.98.0';
import { r2PublicUrl, r2Delete } from '../_shared/r2.ts';

type JsonRecord = Record<string, unknown>;
const MAX_BODY_BYTES = 32_000;
const DEFAULT_ALLOWED_ORIGINS = [
  'http://10.0.2.189:3000',
  'http://localhost:3000',
  'http://127.0.0.1:3000',
  'https://grupo-gsa.com.br',
  'https://www.grupo-gsa.com.br'
];

function isLocalOrigin(origin: string) {
  return /^https?:\/\/(localhost|127\.0\.0\.1|10\.\d+\.\d+\.\d+|192\.168\.\d+\.\d+|172\.(1[6-9]|2\d|3[01])\.\d+\.\d+)(:\d+)?$/.test(origin);
}

function configuredOrigins() {
  const envOrigins = (Deno.env.get('ALLOWED_ORIGINS') || '')
    .split(',')
    .map((origin) => origin.trim())
    .filter(Boolean);
  return [...DEFAULT_ALLOWED_ORIGINS, ...envOrigins];
}

function isAllowedOrigin(origin: string | null): boolean {
  if (!origin) return true;
  if (isLocalOrigin(origin)) return true;
  return configuredOrigins().includes(origin);
}

function corsHeaders(origin: string | null) {
  const allowed = origin && isAllowedOrigin(origin) ? origin : '*';
  return {
    'access-control-allow-origin': allowed,
    'access-control-allow-headers': 'authorization, x-client-info, apikey, content-type, x-cron-secret',
    'access-control-allow-methods': 'POST, OPTIONS',
    'access-control-max-age': '86400',
    'cache-control': 'no-store',
    'x-content-type-options': 'nosniff',
    vary: 'Origin',
  };
}

function json(status: number, body: JsonRecord, origin: string | null = null, extraHeaders: HeadersInit = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', ...corsHeaders(origin), ...extraHeaders },
  });
}

function clientIp(request: Request) {
  return request.headers.get('cf-connecting-ip')
    || request.headers.get('x-real-ip')
    || request.headers.get('x-forwarded-for')?.split(',')[0]?.trim()
    || 'unknown';
}

async function digest(value: string) {
  const bytes = new TextEncoder().encode(value);
  const hash = await crypto.subtle.digest('SHA-256', bytes);
  return Array.from(new Uint8Array(hash)).map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

async function readJsonWithinLimit(request: Request): Promise<JsonRecord> {
  if (!request.body) throw new SyntaxError('invalid_json');
  const reader = request.body.getReader();
  const decoder = new TextDecoder();
  let size = 0;
  let text = '';
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > MAX_BODY_BYTES) throw new RangeError('payload_too_large');
      text += decoder.decode(value, { stream: true });
    }
    text += decoder.decode();
    const parsed = JSON.parse(text);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new SyntaxError('invalid_json');
    return parsed as JsonRecord;
  } finally {
    reader.releaseLock();
  }
}

// Helpers from gsa-public-advertising
const ALLOWED_COMPANY_SIZES = new Set(['autonomo', 'mei', 'micro', 'pequena', 'media', 'grande']);
const ALLOWED_FORMATS = new Set([
  'responsive_banner', 'sponsored_card', 'rectangle', 'sticky_banner', 'hero',
  'inline_video', 'floating_video', 'lightbox', 'section_sponsorship',
  'sponsored_content', 'takeover',
]);
const ALLOWED_PLACEMENTS = new Set([
  'ADS_PUBLIC_SHOWCASE', 'HOME_BANNER_TOP', 'HOME_INLINE_01', 'HOME_LIGHTBOX',
  'SITE_STICKY_BOTTOM', 'MARKETPLACE_SPONSORED_CARD', 'CLASSIFIEDS_BANNER_TOP',
]);
const ALLOWED_DEVICES = new Set(['desktop', 'tablet', 'mobile']);

const DEFAULT_ALLOWED_ORIGINS = [
  'http://10.0.2.189:3000',
  'http://localhost:3000',
  'http://127.0.0.1:3000',
];

function configuredOrigins() {
  return (Deno.env.get('ALLOWED_ORIGINS') || DEFAULT_ALLOWED_ORIGINS.join(','))
    .split(',')
    .map((origin) => origin.trim())
    .filter(Boolean);
}

function corsHeaders(origin: string | null) {
  const allowed = origin || '*';
  return {
    'access-control-allow-origin': allowed,
    'access-control-allow-headers': 'authorization, x-client-info, apikey, content-type, x-custom-header',
    'access-control-allow-methods': 'GET, POST, PUT, DELETE, OPTIONS',
    'access-control-max-age': '86400',
    vary: 'Origin',
  };
}

function json(status: number, body: JsonRecord, origin: string | null, extra: HeadersInit = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', ...corsHeaders(origin), ...extra },
  });
}

function onlyDigits(value: unknown) {
  return String(value || '').replace(/\D/g, '');
}

function normalizeArray(value: unknown, allowed: Set<string>) {
  if (!Array.isArray(value)) return [];
  return Array.from(new Set(
    value
      .map((item) => String(item || '').trim())
      .filter((item) => allowed.has(item)),
  )).slice(0, 20);
}

function isHttpsUrl(value: string) {
  if (!value) return true;
  try {
    return new URL(value).protocol === 'https:';
  } catch {
    return false;
  }
}

function hasRepeatedDigits(value: string) {
  return /^(\d)\1+$/.test(value);
}

export function isValidCpf(value: string) {
  const digits = onlyDigits(value);
  if (digits.length !== 11 || hasRepeatedDigits(digits)) return false;
  const calculate = (length: number) => {
    let sum = 0;
    for (let index = 0; index < length; index += 1) sum += Number(digits[index]) * (length + 1 - index);
    const remainder = (sum * 10) % 11;
    return remainder === 10 ? 0 : remainder;
  };
  return calculate(9) === Number(digits[9]) && calculate(10) === Number(digits[10]);
}

export function isValidCnpj(value: string) {
  const digits = onlyDigits(value);
  if (digits.length !== 14 || hasRepeatedDigits(digits)) return false;
  const calculate = (length: 12 | 13) => {
    const weights = length === 12
      ? [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]
      : [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
    const sum = weights.reduce((total, weight, index) => total + Number(digits[index]) * weight, 0);
    const remainder = sum % 11;
    return remainder < 2 ? 0 : 11 - remainder;
  };
  return calculate(12) === Number(digits[12]) && calculate(13) === Number(digits[13]);
}

function isValidDocument(value: string) {
  return value.length === 11 ? isValidCpf(value) : isValidCnpj(value);
}

function isIsoDate(value: string) {
  if (!value) return true;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const date = new Date(`${value}T00:00:00Z`);
  return Number.isFinite(date.getTime()) && date.toISOString().slice(0, 10) === value;
}

function normalizeSourceMetadata(value: unknown) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const source = value as JsonRecord;
  const pathname = String(source.pathname || '').trim().slice(0, 300);
  const referrer = String(source.referrer || '').trim().slice(0, 500);
  const utmSource = String(source.utm_source || '').trim().slice(0, 120);
  return {
    ...(pathname ? { pathname } : {}),
    ...(referrer ? { referrer } : {}),
    ...(utmSource ? { utm_source: utmSource } : {}),
  };
}
export function normalizePayload(input: unknown) {
  if (!input || typeof input !== 'object') return null;
  const source = input as JsonRecord;
  const payload = {
    company_name: String(source.company_name || '').trim().slice(0, 160),
    document: onlyDigits(source.document).slice(0, 14),
    company_size: String(source.company_size || '').trim(),
    segment: String(source.segment || '').trim().slice(0, 120),
    contact_name: String(source.contact_name || '').trim().slice(0, 120),
    contact_email: String(source.contact_email || '').trim().toLowerCase().slice(0, 180),
    contact_phone: onlyDigits(source.contact_phone).slice(0, 13),
    website: String(source.website || '').trim().slice(0, 300),
    objective: String(source.objective || '').trim().slice(0, 160),
    desired_formats: normalizeArray(source.desired_formats, ALLOWED_FORMATS),
    desired_pages: normalizeArray(source.desired_pages, ALLOWED_PLACEMENTS),
    devices: normalizeArray(source.devices, ALLOWED_DEVICES),
    desired_start_date: String(source.desired_start_date || '').trim().slice(0, 10),
    desired_end_date: String(source.desired_end_date || '').trim().slice(0, 10),
    intended_budget: Number(source.intended_budget || 0),
    needs_creative_service: Boolean(source.needs_creative_service),
    notes: String(source.notes || '').trim().slice(0, 2000),
    website_confirmation: String(source.website_confirmation || '').trim(),
    started_at: String(source.started_at || '').trim(),
    source_metadata: normalizeSourceMetadata(source.source_metadata),
  };

  const emailValid = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(payload.contact_email);
  const today = new Date().toISOString().slice(0, 10);
  const durationDays = payload.desired_start_date && payload.desired_end_date
    ? Math.round((Date.parse(`${payload.desired_end_date}T00:00:00Z`) - Date.parse(`${payload.desired_start_date}T00:00:00Z`)) / 86_400_000)
    : 0;
  const dateRangeValid = isIsoDate(payload.desired_start_date)
    && isIsoDate(payload.desired_end_date)
    && (!payload.desired_start_date || payload.desired_start_date >= today)
    && (!payload.desired_end_date || Boolean(payload.desired_start_date))
    && (!payload.desired_start_date || !payload.desired_end_date || (
      payload.desired_end_date >= payload.desired_start_date && durationDays <= 366
    ));
  const startedAt = Date.parse(payload.started_at);
  const formAge = Date.now() - startedAt;
  const formAgeValid = Number.isFinite(startedAt) && formAge >= 2500 && formAge <= 2 * 60 * 60 * 1000;

  if (
    payload.website_confirmation ||
    payload.company_name.length < 2 ||
    !isValidDocument(payload.document) ||
    !ALLOWED_COMPANY_SIZES.has(payload.company_size) ||
    payload.segment.length < 2 ||
    payload.contact_name.length < 2 ||
    !emailValid ||
    payload.contact_phone.length < 10 ||
    payload.objective.length < 3 ||
    payload.desired_formats.length === 0 ||
    payload.desired_pages.length === 0 ||
    payload.devices.length === 0 ||
    !Number.isFinite(payload.intended_budget) ||
    payload.intended_budget <= 0 ||
    payload.intended_budget > 100_000_000 ||
    !isHttpsUrl(payload.website) ||
    !dateRangeValid ||
    !formAgeValid
  ) return null;

  return payload;
}

// Helpers from gsa-advertiser-access
const ACCESS_ELIGIBLE_STATUSES = new Set([
  'proposal_sent',
  'negotiation_requested',
  'accepted',
]);
const DEFAULT_ALLOWED_ORIGINS = [
  'https://grupo-gsa.com.br',
  'https://www.grupo-gsa.com.br',
  'http://localhost:3000',
  'http://127.0.0.1:3000',
];
function normalizeProtocol(value: unknown) {
  const protocol = String(value || '').trim().toUpperCase();
  return /^[A-Z]{3}-[A-Z0-9-]{8,40}$/.test(protocol) ? protocol : null;
}
function normalizeEmail(value: unknown) {
  const email = String(value || '').trim().toLowerCase();
  return /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) && email.length <= 254 ? email : null;
}
function normalizeDocument(value: unknown) {
  const document = String(value || '').replace(/\D/g, '');
  return document.length === 11 || document.length === 14 ? document : null;
}
async function findUserByEmail(admin: any, email: string) {
  for (let page = 1; page <= 100; page += 1) {
    const { data, error } = await admin.auth.admin.listUsers({ page, perPage: 200 });
    if (error) throw error;
    const match = data?.users?.find((user: any) => String(user.email || '').toLowerCase() === email);
    if (match) return match;
    if ((data?.users?.length || 0) < 200) break;
  }
  return null;
}

// Helpers from gsa-ad-delivery
function cleanIdentifier(value: unknown, max = 160) {
  const normalized = String(value || '').trim();
  if (!normalized || normalized.length > max || !/^[a-zA-Z0-9._:-]+$/.test(normalized)) return null;
  return normalized;
}
export function normalizeServePayload(input: unknown) {
  if (!input || typeof input !== 'object') return null;
  const source = input as JsonRecord;
  const placement = cleanIdentifier(source.placement_code, 80);
  const viewer = cleanIdentifier(source.viewer_id, 160);
  const session = cleanIdentifier(source.session_id, 160);
  const route = String(source.route || '').trim().slice(0, 500);
  const device = String(source.device || '').trim().slice(0, 20);
  if (!placement || !viewer || !session || !['desktop', 'tablet', 'mobile'].includes(device)) return null;
  return { placement, viewer, session, route, device };
}

// Scheduler helper
function safeEqual(left: string, right: string) {
  const leftBytes = new TextEncoder().encode(left);
  const rightBytes = new TextEncoder().encode(right);
  if (leftBytes.length !== rightBytes.length) return false;
  let difference = 0;
  for (let index = 0; index < leftBytes.length; index += 1) difference |= leftBytes[index] ^ rightBytes[index];
  return difference === 0;
}

export async function handleRequest(request: Request) {
  const origin = request.headers.get('origin');
  if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: corsHeaders(origin) });
  if (origin && !isAllowedOrigin(origin)) return json(403, { error: 'origin_not_allowed' }, origin);
  if (request.method !== 'POST') return json(405, { error: 'method_not_allowed' }, origin);

  const supabaseUrl = Deno.env.get('SUPABASE_URL') || '';
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';
  const admin = createClient(supabaseUrl, serviceRoleKey, { auth: { persistSession: false, autoRefreshToken: false } }) as any;

  // Handle Scheduler
  const providedSecret = request.headers.get('x-cron-secret');
  if (providedSecret) {
    const expectedSecret = Deno.env.get('ADVERTISING_CRON_SECRET');
    if (!expectedSecret || !supabaseUrl || !serviceRoleKey) return json(503, { error: 'server_not_configured' });
    if (!safeEqual(providedSecret, expectedSecret)) return json(401, { error: 'invalid_secret' });

    const { data: stateData, error: stateError } = await admin.rpc('gsa_ads_refresh_campaign_states');
    if (stateError) return json(500, { error: 'refresh_failed' });

    const { data: orphanRows, error: orphanError } = await admin.rpc('gsa_ads_list_orphan_creative_paths');
    if (orphanError) return json(500, { error: 'orphan_lookup_failed' });

    const orphanPaths = Array.isArray(orphanRows) ? orphanRows.map((row: any) => String(row?.storage_path || '').trim()).filter(Boolean) : [];
    if (orphanPaths.length > 0) {
      try {
        await r2Delete(orphanPaths.map((p: string) => 'public/ad-creatives/' + p));
      } catch (removalError) {
        return json(500, { error: 'orphan_cleanup_failed' });
      }
    }
    return json(200, { success: true, ...(stateData || {}), orphan_creatives_deleted: orphanPaths.length });
  }

  const declaredLength = Number(request.headers.get('content-length') || 0);
  if (declaredLength > MAX_BODY_BYTES) return json(413, { error: 'payload_too_large' }, origin);

  let body: JsonRecord;
  try {
    body = await readJsonWithinLimit(request);
  } catch (error) {
    return json(error instanceof RangeError ? 413 : 400, { error: error instanceof RangeError ? 'payload_too_large' : 'invalid_json' }, origin);
  }

  const action = String(body.action || '').trim();

  // Handle Ad Delivery
  if (action === 'serve' || action === 'event') {
    if (action === 'serve') {
      const p = normalizeServePayload(body);
      if (!p) return json(400, { error: 'invalid_payload' }, origin);
      const { data, error } = await admin.rpc('gsa_ads_serve', {
        p_placement: p.placement, p_viewer_id: p.viewer, p_session_id: p.session, p_route: p.route, p_device: p.device
      });
      if (error || !data?.ad) return json(404, { error: 'no_ad_available' }, origin);
      return json(200, { success: true, ad: { ...data.ad, creative_url: r2PublicUrl('private/ad-creatives/' + data.ad.storage_path) } }, origin);
    }
    if (action === 'event') {
      const token = cleanIdentifier(body.event_token, 60);
      const eventType = String(body.event_type || '').trim();
      if (!token || !['viewable', 'click', 'video_start', 'video_complete'].includes(eventType)) return json(400, { error: 'invalid_event' }, origin);
      const { data, error } = await admin.rpc('gsa_ads_record_event', { p_event_token: token, p_event_type: eventType });
      if (error) return json(404, { error: 'event_not_found' }, origin);
      return json(200, { success: true, recorded: Boolean(data?.recorded) }, origin);
    }
  }

  // Handle Advertiser Access (validate, register)
  const protocol = normalizeProtocol(body.protocol);
  if (protocol && (action === 'validate' || action === 'register')) {
    const anonKey = Deno.env.get('SUPABASE_ANON_KEY');
    if (!anonKey) return json(503, { error: 'server_not_configured' }, origin);
    const ipHash = await digest(clientIp(request));
    const { data: rateLimit, error: rateError } = await admin.rpc('gsa_auth_rate_limit_check', {
      p_bucket_key: `ads:advertiser-access:${action}:${ipHash}`, p_limit: action === 'validate' ? 20 : 8, p_window_seconds: 3600, p_block_seconds: 7200,
    });
    if (rateLimit?.allowed === false) return json(429, { error: 'too_many_attempts', retry_after: Number(rateLimit.retry_after || 3600) }, origin);

    const { data: validation, error: validationError } = await admin.rpc('gsa_public_validate_advertising_protocol', { p_protocol: protocol });
    if (!validation?.success || !validation?.request) return json(404, { error: 'protocol_not_found' }, origin);
    if (!ACCESS_ELIGIBLE_STATUSES.has(String(validation.request.status || ''))) return json(403, { error: 'advertiser_access_not_approved' }, origin);

    if (action === 'validate') return json(200, { success: true, request: validation.request }, origin);

    const email = normalizeEmail(body.email);
    const document = normalizeDocument(body.document);
    const password = String(body.password || '');
    if (!email || !document || password.length < 8 || password.length > 128) return json(400, { error: 'invalid_registration' }, origin);
    if (email !== String(validation.request.contact_email || '').toLowerCase() || document !== String(validation.request.document || '').replace(/\D/g, '')) {
      return json(403, { error: 'registration_data_mismatch' }, origin);
    }

    let user = await findUserByEmail(admin, email);
    const accountExists = Boolean(user);
    const redirectUrl = new URL('/anuncios/login', origin && configuredOrigins().includes(origin) ? origin : configuredOrigins()[0]);
    redirectUrl.searchParams.set('protocolo', protocol);
    const publicClient = createClient(supabaseUrl, anonKey, { auth: { persistSession: false, autoRefreshToken: false } }) as any;

    if (!user) {
      const { data: created, error: createError } = await publicClient.auth.signUp({
        email, password, options: { emailRedirectTo: redirectUrl.toString(), data: { gsa_role: 'advertiser', protocol } },
      });
      if (createError || !created?.user) return json(502, { error: 'account_creation_failed' }, origin);
      return json(202, { success: true, account_exists: false, verification_required: true }, origin);
    }

    if (!user.email_confirmed_at) {
      await publicClient.auth.resend({ type: 'signup', email, options: { emailRedirectTo: redirectUrl.toString() } });
      return json(202, { success: true, account_exists: true, verification_required: true }, origin);
    }

    const authorization = request.headers.get('authorization') || '';
    const accessToken = authorization.toLowerCase().startsWith('bearer ') ? authorization.slice(7).trim() : '';
    let possessionVerified = false;
    if (accessToken) {
      const { data: tokenUser } = await admin.auth.getUser(accessToken);
      possessionVerified = tokenUser.user?.id === user.id && String(tokenUser.user?.email || '').toLowerCase() === email;
    }
    if (!possessionVerified) {
      const { data: signInData, error: signInError } = await publicClient.auth.signInWithPassword({ email, password });
      possessionVerified = !signInError && signInData.user?.id === user.id && String(signInData.user?.email || '').toLowerCase() === email;
    }
    if (!possessionVerified) return json(401, { error: 'invalid_credentials' }, origin);

    const { data: claimed, error: claimError } = await admin.rpc('gsa_ads_claim_protocol_for_user', { p_protocol: protocol, p_auth_user_id: user.id });
    if (claimError || !claimed?.success) return json(409, { error: 'protocol_claim_failed' }, origin);

    return json(200, { success: true, account_exists: accountExists, verification_required: false, advertiser_status: claimed.advertiser_status }, origin);
  }

  // Handle Public Advertising Request (submit)
  const payload = normalizePayload(body);
  if (payload) {
    const ipHash = await digest(clientIp(request));
    const identityHash = await digest(`${payload.document}:${payload.contact_email}`);
    const { data: ipLimit } = await admin.rpc('gsa_auth_rate_limit_check', { p_bucket_key: `ads:ip:${ipHash}`, p_limit: 8, p_window_seconds: 3600, p_block_seconds: 7200 });
    if (ipLimit?.allowed === false) return json(429, { error: 'too_many_attempts', retry_after: Number(ipLimit.retry_after || 3600) }, origin);
    const { data: identityLimit } = await admin.rpc('gsa_auth_rate_limit_check', { p_bucket_key: `ads:identity:${identityHash}`, p_limit: 5, p_window_seconds: 86400, p_block_seconds: 86400 });
    if (identityLimit?.allowed === false) return json(429, { error: 'too_many_attempts', retry_after: Number(identityLimit.retry_after || 3600) }, origin);

    const { data, error } = await admin.rpc('gsa_public_submit_advertising_request', { p_payload: payload });
    if (error || !data?.success) return json(500, { error: 'request_failed' }, origin);
    return json(201, { success: true, protocol: data.protocol, status: data.status }, origin);
  }

  return json(400, { error: 'invalid_action_or_payload' }, origin);
}

if (import.meta.main) Deno.serve(handleRequest);

﻿/**
 * r2.ts — Módulo compartilhado para acesso ao Cloudflare R2 via API S3
 * Usado pelas Edge Functions do Supabase para upload/download/delete de arquivos.
 *
 * Requer as variáveis de ambiente (Supabase Secrets):
 *   R2_ACCOUNT_ID   — ID da conta Cloudflare
 *   R2_ACCESS_KEY_ID — Access Key ID do R2 API Token
 *   R2_SECRET_ACCESS_KEY — Secret Access Key do R2 API Token
 *   R2_BUCKET_NAME  — Nome do bucket (gsa-hub-storage)
 *   R2_PUBLIC_URL   — URL pública do bucket R2
 */

export const R2_BUCKET = Deno.env.get('R2_BUCKET_NAME') ?? 'gsa-hub-storage';
export const R2_PUBLIC_URL = Deno.env.get('R2_PUBLIC_URL') ?? 'https://pub-7f7b1419c83c407ba9bcf6512329e79a.r2.dev';

const R2_ACCOUNT_ID = () => Deno.env.get('R2_ACCOUNT_ID') ?? '';
const R2_ACCESS_KEY = () => Deno.env.get('R2_ACCESS_KEY_ID') ?? '';
const R2_SECRET_KEY = () => Deno.env.get('R2_SECRET_ACCESS_KEY') ?? '';

function getEndpoint() {
  return `https://${R2_ACCOUNT_ID()}.r2.cloudflarestorage.com`;
}

// ─── AWS Signature V4 ─────────────────────────────────────────────────────────
async function hmac(key: ArrayBuffer | Uint8Array, data: string): Promise<ArrayBuffer> {
  const k = await crypto.subtle.importKey('raw', key, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return crypto.subtle.sign('HMAC', k, new TextEncoder().encode(data));
}

async function sha256hex(data: string | Uint8Array): Promise<string> {
  const buf = typeof data === 'string' ? new TextEncoder().encode(data) : data;
  const hash = await crypto.subtle.digest('SHA-256', buf);
  return Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2, '0')).join('');
}

async function signRequest(
  method: string,
  key: string,
  body: Uint8Array | null,
  contentType?: string,
): Promise<Record<string, string>> {
  const endpoint = getEndpoint();
  const region = 'auto';
  const service = 's3';
  const now = new Date();
  const date = now.toISOString().slice(0, 10).replace(/-/g, '');
  const datetime = now.toISOString().replace(/[-:]/g, '').slice(0, 15) + 'Z';
  const host = new URL(endpoint).host;

  const payloadHash = body ? await sha256hex(body) : 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855';
  const signedHeaders = contentType
    ? 'content-type;host;x-amz-content-sha256;x-amz-date'
    : 'host;x-amz-content-sha256;x-amz-date';

  const canonicalHeaders = contentType
    ? `content-type:${contentType}\nhost:${host}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${datetime}\n`
    : `host:${host}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${datetime}\n`;

  const canonicalPath = `/${R2_BUCKET}/${key.replace(/^\/+/, '')}`;
  const canonicalRequest = [method, canonicalPath, '', canonicalHeaders, signedHeaders, payloadHash].join('\n');

  const credentialScope = `${date}/${region}/${service}/aws4_request`;
  const stringToSign = ['AWS4-HMAC-SHA256', datetime, credentialScope, await sha256hex(canonicalRequest)].join('\n');

  const enc = new TextEncoder();
  const kDate = await hmac(enc.encode(`AWS4${R2_SECRET_KEY()}`), date);
  const kRegion = await hmac(kDate, region);
  const kService = await hmac(kRegion, service);
  const kSigning = await hmac(kService, 'aws4_request');
  const signatureBytes = await hmac(kSigning, stringToSign);
  const signature = Array.from(new Uint8Array(signatureBytes)).map(b => b.toString(16).padStart(2, '0')).join('');

  const authHeader = `AWS4-HMAC-SHA256 Credential=${R2_ACCESS_KEY()}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;

  return {
    Authorization: authHeader,
    'x-amz-date': datetime,
    'x-amz-content-sha256': payloadHash,
    ...(contentType ? { 'Content-Type': contentType } : {}),
  };
}

// ─── Upload de arquivo ────────────────────────────────────────────────────────
export async function r2Upload(
  key: string,
  body: Uint8Array,
  contentType: string,
): Promise<{ publicUrl: string; path: string }> {
  const normalizedKey = key.replace(/^\/+/, '');
  const headers = await signRequest('PUT', normalizedKey, body, contentType);

  const resp = await fetch(`${getEndpoint()}/${R2_BUCKET}/${normalizedKey}`, {
    method: 'PUT',
    headers,
    body,
  });

  if (!resp.ok) {
    const text = await resp.text();
    throw new Error(`R2 upload falhou [${resp.status}]: ${text}`);
  }

  return {
    publicUrl: `${R2_PUBLIC_URL}/${normalizedKey}`,
    path: normalizedKey,
  };
}

// ─── Download de arquivo ──────────────────────────────────────────────────────
export async function r2Download(key: string): Promise<{ body: Uint8Array; contentType: string }> {
  const normalizedKey = key.replace(/^\/+/, '');
  const headers = await signRequest('GET', normalizedKey, null);

  const resp = await fetch(`${getEndpoint()}/${R2_BUCKET}/${normalizedKey}`, { headers });
  if (!resp.ok) throw new Error(`R2 download falhou [${resp.status}]`);

  const body = new Uint8Array(await resp.arrayBuffer());
  const contentType = resp.headers.get('content-type') ?? 'application/octet-stream';
  return { body, contentType };
}

// ─── Delete de arquivo(s) ────────────────────────────────────────────────────
export async function r2Delete(keys: string[]): Promise<void> {
  await Promise.all(
    keys.map(async (key) => {
      const normalizedKey = key.replace(/^\/+/, '');
      const headers = await signRequest('DELETE', normalizedKey, null);
      const resp = await fetch(`${getEndpoint()}/${R2_BUCKET}/${normalizedKey}`, { method: 'DELETE', headers });
      if (!resp.ok && resp.status !== 404) {
        throw new Error(`R2 delete falhou [${resp.status}]: ${key}`);
      }
    }),
  );
}

// ─── URL pública ──────────────────────────────────────────────────────────────
export function r2PublicUrl(key: string): string {
  return `${R2_PUBLIC_URL}/${key.replace(/^\/+/, '')}`;
}

